									<p class="text-xs text-ui-ink-gray-500">Masuk – Keluar</p>
									<p class="text-sm font-semibold text-ui-ink-gray-900">
										{{ jam(detail.waktu_masuk) }} –
										{{ jam(detail.waktu_keluar) }}
									</p>
								</div>
								<div class="rounded-xl p-3" :class="kelompok(detail.kelompok)?.bg">
									<p class="text-xs" :class="kelompok(detail.kelompok)?.teks">
										{{ detail.jenis }}
									</p>
									<p
										class="text-sm font-semibold"
										:class="kelompok(detail.kelompok)?.angka"
									>
										{{ adaDurasi(detail) ? durasiMenit(detail.menit) : '—' }}
									</p>
								</div>
							</div>

							<p class="mt-3 text-sm text-ui-ink-gray-600">
								{{ keteranganKejadian(detail) }}
							</p>

							<div class="mt-4">
								<p class="text-xs text-ui-ink-gray-500">Alasan karyawan</p>
								<p class="mt-1 whitespace-pre-wrap text-sm text-ui-ink-gray-800">
									{{ detail.alasan || '—' }}
								</p>
								<a
									v-if="detail.lampiran"
									:href="detail.lampiran"
									target="_blank"
									rel="noopener"
									class="mt-2.5 flex items-center gap-2 rounded-xl border border-ui-line-gray-200 px-3 py-2 text-sm text-ui-ink-gray-700 active:bg-ui-surface-gray-50"
								>
									<svg
										xmlns="http://www.w3.org/2000/svg"
										viewBox="0 0 24 24"
										class="h-4 w-4 shrink-0 text-ui-ink-gray-400"
										fill="none"
										stroke="currentColor"
										stroke-width="2"
										stroke-linecap="round"
										stroke-linejoin="round"
									>
										<path
											d="M21.44 11.05l-9.19 9.19a6 6 0 0 1-8.49-8.49l9.19-9.19a4 4 0 0 1 5.66 5.66l-9.2 9.19a2 2 0 0 1-2.83-2.83l8.49-8.48"
										/>
									</svg>
									<span class="min-w-0 flex-1 truncate">Lihat lampiran</span>
								</a>
							</div>

							<p
								v-if="detail.alasan_penolakan"
								class="mt-4 rounded-xl bg-ui-surface-red-50 p-3 text-sm text-ui-ink-red-800"
							>
								<span class="font-medium">Alasan penolakan:</span>
								{{ detail.alasan_penolakan }}
							</p>

							<div class="mt-4 rounded-xl bg-ui-surface-gray-50 p-3">
								<p class="text-xs text-ui-ink-gray-600">
									{{ teksRiwayat(detail) }}
								</p>
							</div>

							<div v-if="detail.boleh_diputuskan" class="mt-4">
								<div class="flex gap-2">
									<button
										type="button"
										class="flex-1 rounded-xl border border-ui-line-gray-200 py-2.5 text-sm font-medium text-ui-ink-red-600 active:bg-ui-surface-red-50 disabled:opacity-50"
										:disabled="sibuk"
										@click="mintaTolak([detail.name])"
									>
										Reject
									</button>
									<button
										type="button"
										class="flex-1 rounded-xl bg-primary py-2.5 text-sm font-medium text-ui-onPrimary active:opacity-80 disabled:opacity-50"
										:disabled="sibuk"
										@click="setujui([detail.name])"
									>
										Approve
									</button>
								</div>
								<p
									v-if="ringkasan.level === 'atasan'"
									class="mt-2 text-center text-xs text-ui-ink-gray-400"
								>
									Approve meneruskan ke Ketua untuk keputusan akhir.
								</p>
							</div>
						</div>
					</div>
				</Transition>
			</div>
		</Transition>

		<!-- ============ DIALOG ALASAN PENOLAKAN ============ -->
		<Transition
			enter-active-class="transition-opacity duration-200"
			enter-from-class="opacity-0"
			leave-active-class="transition-opacity duration-150"
			leave-to-class="opacity-0"
		>
			<div
				v-if="tolakUntuk"
				class="fixed inset-0 z-50 flex items-end justify-center bg-black/40 px-5 sm:items-center"
			>
				<Transition
					appear
					enter-active-class="transition-transform duration-200 ease-out"
					enter-from-class="translate-y-full"
					leave-active-class="transition-transform duration-150 ease-in"
					leave-to-class="translate-y-full"
				>
					<div
						v-if="tolakUntuk"
						class="sheet-bottom w-full max-w-sm rounded-t-3xl bg-ui-surface p-5 sm:rounded-3xl"
					>
						<p class="font-medium text-ui-ink-gray-900">
							Reject {{ tolakUntuk.length }} perbaikan absen
						</p>
						<p class="mt-1 text-sm text-ui-ink-gray-500">
							Alasan opsional — bila diisi, terlihat oleh karyawan.
						</p>
						<textarea
							v-model.trim="alasanTolak"
							rows="3"
							placeholder="Alasan penolakan (opsional)"
							class="mt-3 w-full rounded-xl border border-ui-line-gray-200 px-3 py-2 text-sm outline-none placeholder:text-ui-ink-gray-400 focus:border-primary"
						></textarea>
						<p v-if="galatTolak" class="mt-1.5 text-sm text-ui-ink-red-600">
							{{ galatTolak }}
						</p>
						<div class="mt-4 flex gap-2">
							<button
								type="button"
								class="flex-1 rounded-xl border border-ui-line-gray-200 py-2.5 text-sm font-medium text-ui-ink-gray-600 active:bg-ui-surface-gray-50"
								@click="batalTolak"
							>
								Batal
							</button>
							<button
								type="button"
								class="flex-1 rounded-xl bg-red-600 py-2.5 text-sm font-medium text-white active:opacity-80 disabled:opacity-50"
								:disabled="sibuk"
								@click="kirimTolak"
							>
								Reject
							</button>
						</div>
					</div>
				</Transition>
			</div>
		</Transition>
	</div>
</template>

<script setup>
/**
 * Approval Perbaikan Absen — antrean keputusan Atasan (leader department) dan
 * Ketua (Director), untuk keempat jenis masalah absensi sekaligus.
 *
 * Kartu ringkasan = kategori antrean (Menunggu / Di Ketua / Selesai /
 * Kadaluwarsa); chip di bawahnya menyaring jenis (Terlambat, Tidak Scan,
 * Pulang Cepat, Absen) supaya jelas alasan apa yang sedang diputuskan.
 */
import { computed, onMounted, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { createResource } from 'frappe-ui'
import KalenderTanggal from '../components/KalenderTanggal.vue'
import {
	KELOMPOK,
	NAMA_BULAN,
	durasiMenit,
	jam,
	kelompok,
	keteranganKejadian,
	statusBadge,
	tanggalRingkas,
} from '../data/perbaikanAbsenStatus'
import { refreshCsrfToken } from '../data/session'
import { notifyError, notifySuccess } from '../composables/toast'
import { useBackNavigation } from '../composables/useBackNavigation'

const { backTarget, backLabel } = useBackNavigation({ name: 'Home' }, 'Home')
const route = useRoute()

const PER_HALAMAN = 20

// Kartu ringkasan per kategori antrean. Kategori yang tampil datang dari server
// (`ringkasan.kategori`): atasan punya 4, Director 3 — ia tidak punya kartu
// "Di Ketua" karena antrean ketua memang kartu "Menunggu"-nya sendiri.
const KARTU = {
	menunggu: {
		label: 'Menunggu',
		bg: 'bg-ui-surface-amber-50',
		teks: 'text-ui-ink-amber-700',
		angka: 'text-ui-ink-amber-900',
		kosong: 'Tidak ada yang menunggu keputusan Anda.',
	},
	ketua: {
		label: 'Di Ketua',
		bg: 'bg-ui-surface-orange-50',
		teks: 'text-ui-ink-orange-700',
		angka: 'text-ui-ink-orange-800',
		kosong: 'Tidak ada yang sedang menunggu approval ketua.',
	},
	selesai: {
		label: 'Selesai',
		bg: 'bg-ui-surface-green-50',
		teks: 'text-ui-ink-green-700',
		angka: 'text-ui-ink-green-800',
		kosong: 'Belum ada yang selesai diputuskan.',
	},
	kedaluwarsa: {
		label: 'Kadaluwarsa',
		bg: 'bg-ui-surface-red-50',
		teks: 'text-ui-ink-red-700',
		angka: 'text-ui-ink-red-900',
		kosong: 'Tidak ada yang kadaluwarsa.',
	},
}

const hariIni = new Date()
// Null dulu: periode awal diambil dari server (periode cut-off yang berisi hari
// ini), bukan bulan kalender — record bertanggal setelah cut-off masuk periode
// bulan berikutnya.
const bulan = ref(null)
const tahun = ref(null)

const rows = ref([])
const ringkasan = ref({
	menunggu: 0,
	sisa_hari: null,
	cabang: [],
	level: null,
	kategori: ['menunggu'],
})
const start = ref(0)
const hasMore = ref(false)
const loading = ref(false)
const sibuk = ref(false)
const error = ref('')

const cabang = ref('')
const cari = ref('')
const tanggal = ref('')
const kalenderBuka = ref(false)
const kategori = ref('menunggu')
// Jenis bisa dibawa dari luar (?jenis=terlambat), mis. dari Workflow Requests.
const kelompokAktif = ref(
	KELOMPOK.some((k) => k.key === route.query.jenis) ? route.query.jenis : ''
)
const sheetJenis = ref(false)
const modePilih = ref(false)
const terpilih = ref(new Set())
const detail = ref(null)
const tolakUntuk = ref(null)
const alasanTolak = ref('')
const galatTolak = ref('')

const pilihanJenis = [
	{ key: '', label: 'Semua jenis', titik: 'border-ui-line-gray-300' },
	...KELOMPOK,
]

// HR memakai kategori yang sama dengan atasan tetapi tidak memutuskan apa pun,
// jadi "Menunggu" bagi HR berarti antrean yang masih di tingkat Atasan.
const KARTU_HR = {
	menunggu: { label: 'Di Atasan', kosong: 'Tidak ada yang menunggu approval atasan.' },
}
function kartu(key) {
	const k = KARTU[key]
	return ringkasan.value.level === 'hr' && KARTU_HR[key] ? { ...k, ...KARTU_HR[key] } : k
}

const daftarKartu = computed(() =>
	(ringkasan.value.kategori || ['menunggu']).map((key) => ({ key, ...kartu(key) }))
)

const teksKosong = computed(() =>
	tanggal.value || cari.value || cabang.value || kelompokAktif.value
		? 'Tidak ada yang cocok dengan filter ini.'
		: kartu(kategori.value)?.kosong || 'Tidak ada data.'
)

const labelPeriode = computed(() =>
	bulan.value ? `Periode ${NAMA_BULAN[bulan.value - 1]} ${tahun.value}` : 'Periode berjalan'
)

// Periode setelah bulan berjalan belum punya data; majunya dikunci supaya tidak
// terlihat seperti datanya hilang.
const bolehMaju = computed(
	() =>
		tahun.value < hariIni.getFullYear() ||
		(tahun.value === hariIni.getFullYear() && bulan.value < hariIni.getMonth() + 1)
)

function inisial(nama) {
	return String(nama || '?')
		.split(/\s+/)
		.slice(0, 2)
		.map((w) => w[0] || '')
		.join('')
		.toUpperCase()
}

// Hanya Terlambat & Pulang Cepat yang punya durasi; jenis lain cukup jenisnya.
function adaDurasi(row) {
	return ['Terlambat', 'Pulang Cepat'].includes(row?.jenis)
}

function warnaMenit(row) {
	const m = Number(row.menit) || 0
	if (m >= 30) return 'text-ui-ink-red-600'
	if (m >= 10) return 'text-ui-ink-amber-600'
	return 'text-ui-ink-gray-600'
}

function teksRiwayat(row) {
	const r = row.riwayat_periode
	const label = (kelompok(row.kelompok)?.label || row.jenis || '').toLowerCase()
	if (!r || !r.total) return `Periode ini: ${label} pertama`
	return `Periode ini: ${r.total} kali ${label}, ${r.approved} approved`
}

const list = createResource({
	url: 'juragan.api.portal.perbaikan_absen.get_antrean',
	auto: false,
	makeParams() {
		return {
			bulan: bulan.value ?? undefined,
			tahun: tahun.value ?? undefined,
			cabang: cabang.value || undefined,
			q: cari.value || undefined,
			tanggal: tanggal.value || undefined,
			kategori: kategori.value,
			kelompok: kelompokAktif.value || undefined,
			limit: PER_HALAMAN,
			start: start.value,
		}
	},
	onSuccess(data) {
		const batch = data || []
		rows.value = start.value === 0 ? batch : rows.value.concat(batch)
		hasMore.value = batch.length === PER_HALAMAN
		loading.value = false
	},
	onError(err) {
		error.value = err?.messages?.[0] || err?.message || String(err)
		loading.value = false
	},
})

const ringkas = createResource({
	url: 'juragan.api.portal.perbaikan_absen.get_ringkasan_antrean',
	auto: false,
	makeParams() {
		return {
			bulan: bulan.value ?? undefined,
			tahun: tahun.value ?? undefined,
			cabang: cabang.value || undefined,
			q: cari.value || undefined,
			tanggal: tanggal.value || undefined,
			kelompok: kelompokAktif.value || undefined,
		}
	},
	onSuccess(data) {
		if (data) {
			ringkasan.value = data
			// Sinkronkan nav ke periode yang dipakai server saat halaman baru dibuka.
			if (bulan.value == null && data.bulan) {
				bulan.value = data.bulan
				tahun.value = data.tahun
			}
		}
	},
	// Handler wajib ada meski kosong: resource tanpa onError melepas unhandled
	// rejection, dan handler global memunculkan toast KEDUA untuk error yang sama.
	onError() {},
})

const detailRes = createResource({
	url: 'juragan.api.portal.perbaikan_absen.get_detail',
	auto: false,
	onError(err) {
		notifyError(err, 'Gagal membuka detail')
	},
})

const putuskanRes = createResource({
	url: 'juragan.api.portal.perbaikan_absen.putuskan_massal',
	auto: false,
	onError() {},
})

function reload() {
	error.value = ''
	start.value = 0
	loading.value = true
	terpilih.value = new Set()
	list.fetch()
	ringkas.fetch()
}

function muatLagi() {
	start.value += PER_HALAMAN
	loading.value = true
	list.fetch()
}

function geserPeriode(arah) {
	if (bulan.value == null) return
	let b = bulan.value + arah
	let t = tahun.value
	if (b < 1) {
		b = 12
		t -= 1
	} else if (b > 12) {
		b = 1
		t += 1
	}
	bulan.value = b
	tahun.value = t
	// Tanggal terpilih milik periode lama; membawanya ke periode baru hanya
	// menghasilkan daftar kosong.
	tanggal.value = ''
	reload()
}

function pilihCabang(c) {
	cabang.value = c
	reload()
}

function pilihKelompok(k) {
	sheetJenis.value = false
	if (kelompokAktif.value === k) return
	kelompokAktif.value = k
	reload()
}

function pilihKategori(k) {
	if (kategori.value === k) return
	kategori.value = k
	// Hanya kategori "menunggu" yang bisa diputuskan, jadi mode pilih ditutup.
	modePilih.value = false
	reload()
}

function hapusTanggal() {
	tanggal.value = ''
	reload()
}

// Pencarian jalan sambil mengetik, dengan jeda singkat supaya tiap ketukan
// tidak memicu permintaan sendiri.
let tundaCari = null
watch(cari, () => {
	clearTimeout(tundaCari)
	tundaCari = setTimeout(reload, 300)
})

function togglePilih(name) {
	// Set diganti utuh, bukan dimutasi: Vue tidak melacak perubahan isi Set.
	const s = new Set(terpilih.value)
	if (s.has(name)) s.delete(name)
	else s.add(name)
	terpilih.value = s
}

// Detail dibuka sebagai lembar dari bawah, bukan halaman terpisah: memutuskan
// puluhan perbaikan berarti bolak-balik, dan tiap perpindahan halaman berarti
// kehilangan posisi gulir serta filter yang sedang dipakai.
// Di mode pilih, menekan kartu berarti memilihnya — itu yang sedang dikerjakan
// user, dan menyodorkan detail justru memotong pekerjaannya.
function tekanKartu(row) {
	if (modePilih.value && row.boleh_diputuskan) {
		togglePilih(row.name)
		return
	}
	bukaDetail(row)
}

async function bukaDetail(row) {
	// Lembar dibuka SEKARANG dari data yang sudah ada di kartu; riwayat
	// lengkapnya menyusul dari server.
	detail.value = { ...row }

	const d = await detailRes.fetch({ name: row.name })
	// Balasan bisa datang setelah user menutup lembarnya atau membuka kartu
	// lain; menimpanya akan menampilkan orang yang salah.
	if (!d || detail.value?.name !== row.name) return

	// `boleh_diputuskan` & `riwayat_periode` antrean dipertahankan: keduanya
	// dihitung menurut level pemutus, yang tidak diketahui endpoint detail.
	detail.value = {
		...detail.value,
		...d,
		boleh_diputuskan: row.boleh_diputuskan,
		riwayat_periode: row.riwayat_periode,
	}
}

async function jalankan(names, action, alasan) {
	if (!names.length || sibuk.value) return
	sibuk.value = true
	try {
		const hasil = await putuskanRes.submit({
			names: JSON.stringify(names),
			action,
			alasan_penolakan: alasan,
		})
		const berhasil = hasil?.berhasil?.length || 0
		const gagal = hasil?.gagal || []
		if (berhasil) {
			notifySuccess(`${berhasil} perbaikan absen ${teksHasil(action)}.`)
		}
		// Sebagian gagal bukan kegagalan seluruhnya — yang berhasil tetap
		// dilaporkan, dan sisanya disebut apa adanya.
		if (gagal.length) {
			notifyError(
				new Error(gagal[0].pesan || 'Sebagian gagal diproses.'),
				`${gagal.length} gagal diproses`
			)
		}
		detail.value = null
		reload()
	} catch (e) {
		notifyError(e, 'Gagal menyimpan keputusan')
	} finally {
		sibuk.value = false
	}
}

function teksHasil(action) {
	if (action !== 'Approve') return 'di-reject'
	return ringkasan.value.level === 'atasan' ? 'diteruskan ke ketua' : 'di-approve'
}

function setujui(names) {
	jalankan(names, 'Approve')
}

function mintaTolak(names) {
	tolakUntuk.value = names
	alasanTolak.value = ''
	galatTolak.value = ''
}

function batalTolak() {
	tolakUntuk.value = null
	galatTolak.value = ''
}

async function kirimTolak() {
	const names = tolakUntuk.value
	tolakUntuk.value = null
	await jalankan(names, 'Reject', alasanTolak.value)
}

onMounted(async () => {
	await refreshCsrfToken()
	reload()
})
</script>
